        if (*cursor == '{' || *cursor == '[') {
            depth++;
            cursor++;
            continue;
        }
        if (*cursor == '}' || *cursor == ']') {
            depth--;
            cursor++;
            continue;
        }
        if (*cursor != '"') {
            cursor++;
            continue;
        }
        const char *start = ++cursor;
        bool escaped = false;
        while (*cursor && *cursor != '"') {
            if (*cursor == '\\' && cursor[1]) {
                escaped = true;
                cursor += 2;
            } else
                cursor++;
        }
