            return NULL;
        const char *end = cursor++;
        if (depth != 1 || escaped || (size_t)(end - start) != key_length ||
            strncmp(start, key, key_length))
            continue;
        while (*cursor == ' ' || *cursor == '\t' || *cursor == '\r' || *cursor == '\n')
            cursor++;
        if (*cursor != ':')
            continue;
        do {
            cursor++;
        } while (*cursor == ' ' || *cursor == '\t' || *cursor == '\r' || *cursor == '\n');
        return cursor;
    }
    return NULL;
}

